/**
 * social-tweet — X-style post card on a media background.
 *
 * Card visuals + motion live in the TweetCard primitive
 * (src/lib/primitives/social/TweetCard.tsx). This template wires the
 * scene background + variable schema + primitive together.
 */

import * as React from "react";
import type { VariableField } from "../video-config";
import type { SceneTemplateProps } from "./types";
import { resolveTokens } from "./tokens";
import { SceneBackground, mediaBackgroundSchemaFields, mediaBackgroundDefaults } from "./scene-background";
import { TweetCard, hashHue } from "../primitives/social/TweetCard";

export const socialTweetSchema: Record<string, VariableField> = {
  authorName: {
    type: "string",
    label: "Author name",
    default: "Your brand",
    required: true,
    description: "Display name shown bold next to the verified checkmark.",
  },
  authorHandle: {
    type: "string",
    label: "Handle",
    default: "",
    description: "Username in @format. Leave empty to auto-derive from author name (e.g. 'Linear' → '@linear').",
  },
  authorVerified: {
    type: "boolean",
    label: "Verified checkmark",
    default: true,
    description: "Show the blue verified checkmark next to the author name.",
  },
  message: {
    type: "string",
    label: "Tweet text",
    default: "Just shipped the new feature 🚀",
    required: true,
    description: "The tweet/post content. Reads best at 1-3 lines (~80-180 chars). Emoji land naturally at the end of a phrase.",
  },
  likes: {
    type: "number",
    label: "Likes",
    default: 602,
    description: "Target like count (rolls up from 0).",
  },
  replies: {
    type: "number",
    label: "Replies",
    default: 19,
    description: "Target reply count (rolls up from 0).",
  },
  ...mediaBackgroundSchemaFields,
};

export const socialTweetDefaults: Record<string, unknown> = {
  authorName: "Your brand",
  authorHandle: "",
  authorVerified: true,
  message: "Just shipped the new feature 🚀",
  likes: 602,
  replies: 19,
  ...mediaBackgroundDefaults,
};

export const SocialTweetTemplate: React.FC<SceneTemplateProps> = ({
  variables,
  style,
  progress,
  beatIntensity,
  width,
  height,
  sceneDuration,
  isPlaying = true,
  backgroundEffect,
}) => {
  const authorName = String(variables.authorName || "Your brand");
  const message = String(variables.message || "");
  // Per-author hashed hue is an intentional divergence from the canonical
  // accent fallback — routed through the resolver as accentFallback.
  const { accent } = resolveTokens(style, {
    accentFallback: `hsl(${hashHue(authorName)}, 60%, 55%)`,
  });
  const seed = (authorName + message).split("").reduce((acc, c) => acc + c.charCodeAt(0), 0);

  /* Boolean field — but accept the legacy string "false" too in case a
   * saved scene wrote it as text before the type changed. */
  const verifiedRaw = variables.authorVerified;
  const isVerified =
    verifiedRaw === false || String(verifiedRaw ?? "").toLowerCase() === "false"
      ? false
      : true;

  return (
    <div
      style={{
        width,
        height,
        backgroundColor: "#000",
        position: "relative",
        overflow: "hidden",
        fontFamily: "'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      {/* [slot: background] Gradient / media backdrop */}
      <SceneBackground
        style={style}
        progress={progress}
        sceneDuration={sceneDuration}
        width={width}
        height={height}
        mediaUrl={String(variables.mediaUrl || "")}
        mediaType={String(variables.mediaType || "auto")}
        mediaPoster={String(variables.mediaPoster || "")}
        backgroundEffect={backgroundEffect}
        seed={seed}
        isPlaying={isPlaying}
        beatIntensity={beatIntensity}
      />

      {/* [slot: hero] Tweet card — TweetCard primitive (post text is the
          content; no separate caption slot) */}
      <TweetCard
        progress={progress}
        authorName={authorName}
        authorHandle={String(variables.authorHandle || "")}
        authorVerified={isVerified}
        message={message}
        targetLikes={Number(variables.likes) || 602}
        targetReplies={Number(variables.replies) || 19}
        accent={accent}
        width={width}
        height={height}
        beatIntensity={beatIntensity}
      />
    </div>
  );
};

/**
 * TweetCard
 *
 * X-style post card: avatar + name + verified + handle on the left, X logo
 * top-right, tweet text below, footer with comment + heart counter rolls.
 * Card scales in via spring; counters roll up from 0 over the back half.
 *
 * social-tweet.tsx is refactored to consume this primitive; both paths
 * render byte-identical DOM.
 */

import * as React from "react";
import { interpolate, spring, SPRING_SMOOTH } from "../../react-animations/animation-utils";
import { autoTextColor } from "../../scene-templates/color-utils";
import { stripPipe } from "../../scene-templates/text-utils";
import { renderWithEmoji } from "../../emoji/emoji-text";

const CLAMP = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };

const X = {
  cardBg: "#16181c",
  cardBorder: "#2f3336",
  text: "rgb(230, 230, 230)",
  muted: "#71767b",
  verified: "#1d9bf0",
};

export function formatCount(n: number): string {
  // Boundary rule: never let the leading number reach 4 digits — promote
  // to the next unit. Without this, 999,999 likes rounded to "1000K"
  // (mathematically right but breaks the K-suffix convention). Each
  // branch double-checks the rounded value: if rounding would push it
  // ≥1000, fall through to the next unit so 999,500 ≤ n < 1,000,000
  // displays as "1M" not "1000K".
  const abs = Math.abs(n);
  const sign = n < 0 ? "-" : "";
  if (abs < 1_000) return n.toLocaleString();
  if (abs < 10_000) {
    const v = abs / 1_000;
    const rounded = Number(v.toFixed(1));
    if (rounded < 10) return `${sign}${rounded.toString().replace(/\.0$/, "")}K`;
    // falls through to the integer-K branch
  }
  if (abs < 1_000_000) {
    const k = Math.round(abs / 1_000);
    if (k < 1_000) return `${sign}${k}K`;
    // falls through to M
  }
  if (abs < 10_000_000) {
    const v = abs / 1_000_000;
    const rounded = Number(v.toFixed(1));
    if (rounded < 10) return `${sign}${rounded.toString().replace(/\.0$/, "")}M`;
  }
  if (abs < 1_000_000_000) {
    const m = Math.round(abs / 1_000_000);
    if (m < 1_000) return `${sign}${m}M`;
  }
  const v = abs / 1_000_000_000;
  return `${sign}${v.toFixed(1).replace(/\.0$/, "")}B`;
}

export function hashHue(str: string): number {
  let h = 0;
  for (let i = 0; i < str.length; i++) h = (h * 31 + str.charCodeAt(i)) % 360;
  return h;
}

export function deriveHandle(brandName: string): string {
  const slug = brandName.toLowerCase().replace(/[^a-z0-9]/g, "");
  return slug ? `@${slug}` : "";
}

const XLogo: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size} height={size} viewBox="0 0 1200 1227" fill="none">
    <path
      d="M714.163 519.284 1160.89 0h-105.86L667.137 450.887 357.328 0H0l468.492 681.821L0 1226.37h105.866l409.625-476.152 327.181 476.152H1200L714.137 519.284h.026ZM569.165 687.828l-47.468-67.894-377.686-540.24h162.604l304.797 435.991 47.468 67.894 396.2 566.721H892.476L569.165 687.854v-.026Z"
      fill={X.text}
    />
  </svg>
);

const VerifiedBadge: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size} height={size} viewBox="0 0 22 22" fill="none">
    <path
      d="M20.396 11c-.018-.646-.215-1.275-.57-1.816-.354-.54-.852-.972-1.438-1.246.223-.607.27-1.264.14-1.897-.131-.634-.437-1.218-.882-1.687-.47-.445-1.053-.75-1.687-.882-.633-.13-1.29-.083-1.897.14-.273-.587-.704-1.086-1.245-1.44C12.276 1.819 11.647 1.62 11 1.604c-.646.017-1.273.213-1.813.568s-.969.854-1.24 1.44c-.608-.223-1.267-.272-1.902-.14-.635.13-1.22.436-1.69.882-.445.47-.749 1.055-.878 1.688-.13.633-.08 1.29.144 1.896-.587.274-1.087.705-1.443 1.245-.356.54-.555 1.17-.574 1.817.02.647.218 1.276.574 1.817.356.54.856.972 1.443 1.245-.224.606-.274 1.263-.144 1.896.13.634.433 1.218.877 1.688.47.443 1.054.747 1.687.878.633.132 1.29.084 1.897-.136.274.586.705 1.084 1.246 1.439.54.354 1.17.551 1.816.569.647-.016 1.276-.213 1.817-.567s.972-.854 1.245-1.44c.604.239 1.266.296 1.903.164.636-.132 1.22-.447 1.68-.907.46-.46.776-1.044.908-1.681s.075-1.299-.165-1.903c.586-.274 1.084-.705 1.439-1.246.354-.54.551-1.17.569-1.816zM9.662 14.85L6.8 12.46l1.41-1.42 2.262 2.26 4.798-5.23 1.47 1.36-6.198 6.77z"
      fill={X.verified}
    />
  </svg>
